// Omniflow hotfix 1 for the redesign patch (run AFTER
// add_batch_1271_1300_redesign.mjs): restores the 32 glue files the
// redesigned tree imports but the redesign patcher does not carry -
// lib/omniflow session/control-plane glue (session-cookies,
// session-constants, control-plane, portal, auth-dal, client-session),
// lib/supabase clients, lib/content + lib/settings, the admin content
// server actions, and shared client components (Reveal,
// WebsiteChatWidget, useUnreadCount). Fixes: Module not found: Can't
// resolve './session-cookies' (and any other glue file the bad
// folder-copy accident clobbered). Whole-file writeNewRepair ops
// (marker-guarded, backup on drift, .pre_hotfix1.bak); idempotent; a target
// path that exists as a DIRECTORY is renamed to <path>.dir_conflict.bak
// and the real file is written.
import fs from "fs";
const BACKUP_TAG = ".pre_hotfix1.bak";
let applied = 0;
let already = 0;
let warnings = 0;
function writeNewRepair(repoPath, marker, isCp, content) {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY on this machine (copy/extract accident) - renamed to " + target + "; writing the real file.");
      warnings++;
    } else {
      existed = true;
    }
  }
  if (!existed) {
    const parent = repoPath.replace(/\/[^/]*$/, "");
    if (parent !== repoPath) fs.mkdirSync(parent, { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    console.log("+ " + repoPath + " (restored - was missing)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
}
